const status=flow.get('camStatus')||{};
const keys=['play2','prod1','adentro','cam190','cam151','cam67','cam64','bal1_afuera','pt_galpon','molino_chino','fondo','camcom2','playon1','cam96'];
const names={'play2':'Play2','prod1':'Produccion1','adentro':'Adentro','cam190':'CAM190','cam151':'CAM151','cam67':'CAM67','cam64':'CAM64','bal1_afuera':'BAL1 Afuera','pt_galpon':'PT Galpon','molino_chino':'Molino Chino','fondo':'Fondo','camcom2':'CamCom2','playon1':'Playon1','cam96':'CAM96'};
const now=Date.now(); const OLD_SEC=90;
msg.payload=keys.map(k=>{
  const s=status[k]||{};
  const age=s.lastUpdate?Math.floor((now-s.lastUpdate)/1000):null;
  let st=s.status||'unknown';
  if(st==='ok'&&age!==null&&age>OLD_SEC)st='old';
  let txt=age!==null?(st==='error'?'Error (hace '+age+'s)':st==='old'?'Vieja (hace '+age+'s)':'Hace '+age+'s'):(st==='error'?'Error: '+(s.error||''):'Sin datos');
  const kb=s.lastSize?Math.round(s.lastSize/1024)+' KB':'--';
  return{key:k,name:names[k]||k,status:st,statusText:txt,sizeText:kb,ts:s.lastUpdate||0};
});
return msg;
